/* El soporte que se sube desde la fila de un egreso ya registrado. Mismo
   endpoint y misma regla de tipo que el alta. */
document.addEventListener("change", function(e){
  var inp = e.target.closest ? e.target.closest("[data-eg-soporte]") : null;
  if (!inp || !inp.files || !inp.files[0]) return;
  var f = inp.files[0], num = inp.getAttribute("data-eg-soporte");
  var tipo = /\\.xml$/i.test(f.name) ? "application/xml" : "application/pdf";
  inp.disabled = true;
  fetch("/api/admin/egreso/" + encodeURIComponent(num) + "/soporte", {
    method: "POST", headers: { "content-type": tipo }, body: f
  }).then(conEstado).then(function(r){
    if (fallo(r.http, r.d)){ inp.disabled = false; inp.value = ""; return; }
    cargarEgresos();
  }).catch(function(){ inp.disabled = false; alert("No se pudo subir: revisa la conexión."); });
});

document.addEventListener("change", function(e){
  /* Al elegir el archivo se lee ANTES de cargar nada, por dos razones: rellenar
     el correo que el respaldo trae —teclearlo mal atribuye a otra persona un
     documento firmado— y decir qué hay dentro antes de mandarlo. */
  if (e.target.id === "imp-arch"){ mirarRespaldo(); return; }
  var inp = e.target.closest("[data-foto]");
  if (!inp || !inp.files || !inp.files[0]) return;
  var f = inp.files[0];
  inp.value = "";
  /* EL TEXTO ALTERNATIVO SE PREGUNTA; YA NO SALE DEL NOMBRE DEL ARCHIVO.
     Antes el alt era el nombre sin extension, y ese nombre sale publicado en
     /evidencia: «IMG_4821» no describe nada, y «casa_de_Maria_calle_12» dice
     justo lo que el acta promete no decir. Auditoria del 28 sep 2026.
     Cancelar no sube nada; dejarlo vacio sube la foto sin descripcion. */
  var alt = window.prompt("Describe la foto en una frase corta. Sale como texto alternativo en la " +
    "página pública de evidencia: sin nombres de personas ni direcciones.\\n\\nPuedes dejarlo vacío.", "");
  if (alt === null) return;
  /* El cuerpo va crudo con su content-type: sin multipart no hay que parsear
     nada en el Worker, y el nombre del archivo lo pone el servidor. */
  fotoSinMetadatos(f).then(function(limpia){
    return fetch("/api/admin/entrega/" + encodeURIComponent(inp.getAttribute("data-foto")) + "/foto?alt=" +
          encodeURIComponent(String(alt).trim()), {
      method: "POST", headers: {"content-type": "image/jpeg"}, body: limpia
    });
  }, function(){
    throw new Error("lienzo");
  }).then(function(r){ return r.json(); })
    .then(function(d){ if (d.error) alert("No se pudo subir: " + (d.ayuda || d.error)); cargarEntregas(); })
    .catch(function(x){
      alert(String(x && x.message) === "lienzo"
        ? "Este navegador no pudo leer la foto (¿HEIC?). Expórtala como JPG y vuelve a subirla."
        : "No se pudo subir la foto.");
    });
});

/* LA FOTO DE EVIDENCIA PASA POR UN LIENZO ANTES DE SALIR DEL NAVEGADOR.
   Estas fotos se publican en /evidencia, y la foto cruda de un telefono trae
   en su EXIF la latitud y longitud de donde se tomo: la casa de la familia
   que recibio. La auditoria del 28 sep 2026 encontro diez fotos del sitio
   con ese bloque intacto. Redibujar en un canvas y exportar JPEG deja solo
   los pixeles; imageOrientation hornea el giro del EXIF para que la foto no
   salga acostada al perderlo.
   A diferencia de comprimirEnRuta, aqui NO hay plan B con el original: si el
   navegador no puede decodificarla, no se sube. Alli la foto es privada y
   perderla es peor; aqui es publica y lo peor es publicar la ubicacion.
   El servidor vuelve a limpiarla al guardarla y al servirla (sinMetadatosFoto). */
function fotoSinMetadatos(file){
  if (typeof createImageBitmap !== "function") return Promise.reject(new Error("lienzo"));
  return createImageBitmap(file, { imageOrientation: "from-image" }).then(function(bm){
    var k = Math.min(1, 2000 / Math.max(bm.width, bm.height));
    var cv = document.createElement("canvas");
    cv.width = Math.round(bm.width * k); cv.height = Math.round(bm.height * k);
    var cx = cv.getContext("2d");
    /* Fondo blanco: un PNG con transparencia saldria negro en JPEG. */
    cx.fillStyle = "#fff"; cx.fillRect(0, 0, cv.width, cv.height);
    cx.drawImage(bm, 0, 0, cv.width, cv.height);
    if (bm.close) bm.close();
    return new Promise(function(res, rej){
      cv.toBlob(function(b){ if (b) res(b); else rej(new Error("lienzo")); }, "image/jpeg", 0.85);
    });
  });
}

document.addEventListener("click", function(e){
  if (e.target.id === "e-crear"){
    var b = e.target, err = document.getElementById("e-error");
    err.style.display = "none"; err.style.color = "#c0392b";
    b.disabled = true; b.textContent = "Registrando…";
    function v(id){ var el = document.getElementById(id); return el ? el.value : ""; }
    fetch("/api/admin/entrega", {
      method: "POST", headers: {"content-type":"application/json"},
      body: JSON.stringify({
        destino_id: v("e-destino"), sector: v("e-sector"), fecha: v("e-fecha"),
        lugar: v("e-lugar"), aliada: v("e-aliada"), familias: v("e-familias"),
        recibido_por: v("e-recibido"), resumen: v("e-resumen")
      })
    }).then(function(r){ return r.json().then(function(d){ return {http:r.status, d:d}; }); })
      .then(function(res){
        b.disabled = false; b.textContent = "Registrar";
        if (res.http !== 200){
          err.textContent = res.d.faltan ? ("Faltan datos: " + res.d.faltan.join(", ") + ".")
                        : (res.d.ayuda || ("No se pudo registrar (" + (res.d.error||res.http) + ")."));
          err.style.display = "block"; return;
        }
        /* El aviso NO es un error: el acta quedo registrada. Se enseña en el
           mismo sitio pero en ambar, que es como este panel dice «mira esto»
           sin decir «fallo». */
        if (res.d && res.d.aviso){
          err.textContent = res.d.aviso;
          err.style.color = "#b7791f";
          err.style.display = "block";
        }
        pintarCampos(); cargarEntregas();
      })
      .catch(function(){ b.disabled = false; b.textContent = "Reintentar"; });
    return;
  }
  var pb = e.target.closest("[data-pub]");
  if (pb){
    var quiere = pb.getAttribute("data-v") === "1";
    pb.disabled = true; pb.textContent = "…";
    fetch("/api/admin/entrega/" + encodeURIComponent(pb.getAttribute("data-pub")) + "/publicar", {
      method: "POST", headers: {"content-type":"application/json"},
      body: JSON.stringify({ publicar: quiere })
    }).then(function(r){ return r.json(); })
      .then(function(d){
        /* Un error sin «ayuda» (no_encontrada, por ejemplo) se callaba. */
        if (d.ayuda) alert(d.ayuda); else if (d.error) alert("No se pudo: " + d.error); else if (d.aviso) alert(d.aviso);
        cargarEntregas(); cargarSalud(); })
      .catch(function(){ cargarEntregas(); });
  }

  /* Anular pide motivo y avisa que no se deshace. Dos frenos y no uno porque el
     botón vive al lado de «Despublicar», que sí es reversible. */
  var an = e.target.closest("[data-anu]");
  if (an){
    var num = an.getAttribute("data-anu");
    var motivo = window.prompt("Anular " + num + " — no se puede deshacer.\\n\\n¿Por qué se anula? (queda escrito y explica el hueco en el consecutivo)");
    if (!motivo) return;
    an.disabled = true; an.textContent = "…";
    fetch("/api/admin/entrega/" + encodeURIComponent(num) + "/anular", {
      method: "POST", headers: {"content-type":"application/json"},
      body: JSON.stringify({ motivo: motivo })
    }).then(function(r){ return r.json(); })
      .then(function(d){ if (d.ayuda) alert(d.ayuda); else if (d.error) alert("No se pudo anular: " + d.error);
        cargarEntregas(); cargarSalud(); })
      .catch(function(){ cargarEntregas(); });
  }
});

