    postJ("/api/admin/jornada/" + encodeURIComponent(b.getAttribute("data-jcerrar")) + "/cerrar", {
      beneficiarios_directos: vj("j-bd"), beneficiarios_indirectos: vj("j-bi"), beneficiarios_nota: vj("j-bn")
    }, "j-est-msg", b, refrescarJ);
